function IdolLive3D_Demo:__init( main_ )
    
    self.idolLive3D_Main = main_
    self.demoJson = self.idolLive3D_Main.baseJson.data.oths.demo
    assert( isNotNull(self.demoJson) )
    assert( self.demoJson.isDemo == true )
    --- 

    self.uiHandEnv = self.idolLive3D_Main.uiMain.uiHandEnv
    assert( isNotNull(self.uiHandEnv) )

    self.tgtState = self.idolLive3D_Main.baseJson:FindDemoInteractiveState() -- 试玩动作
    assert( isNotNull(self.tgtState) )

    ---
    self.tgtTF = nil
    local allRoleColliders = IdolLive3D_Utils.FindAllRoleColliders( self.idolLive3D_Main.roleTF, true )
    for idStr,collider in pairs(allRoleColliders) do 
        if string.lower(idStr) == string.lower(self.tgtState.desc) then 
            self.tgtTF = collider.transform
            break
        end
    end 
    assert( isNotNull(self.tgtTF) )

    --  
    self.isLastFreeTrackCameraInRange = nil -- 保证一定和第一个检测到的 bool 值不同
    self.isLastShow = nil -- 保证一定和第一个检测到的 bool 值不同
    self.isShow = true 
    self.state = State.Show
    self.playTimes = 0

    ---
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
    self.events = CfUtils.EventsDecorated({
        [IdolLive3D_States.EventNewInteractiveState]    = Bind(self, self.OnNewInteractiveState),
        [IdolLive3D_States.EventSimpleTapInAnyTime]     = function(idStr_)
            -- "_" 表示点击到了 空屏幕, 此时无需跳字:
            if string.lower(idStr_) ~= string.lower(self.tgtState.desc) and string.isEmpty(idStr_) == false and idStr_ ~= "_" then 
                -- local goodsType = GoodsUtils.GetIdType(self.idolLive3D_Main.skinId)
                -- assert( goodsType == Constants.IDType.CardSkin )

                if IdolLive3D_Utils.isRegionSupportHeXie() then 
                    local goodsVo = IdolLive3D_Utils.GetLive3dGoodsVo(self.idolLive3D_Main.skinId)
                    GameUtils.Toast( localize("拥有互动情景\"_name_\"后才能继续深入互动",{_name_=goodsVo.name}) ) -- 飘字
                else
                    local cardConfMgr = CardConfMgr:GetInstance()
                    local skinConf = cardConfMgr:GetCardSkinBySkinId(self.idolLive3D_Main.skinId)
                    --printError("name = " .. tostring(skinConf.name))
                    GameUtils.Toast( localize("拥有_name_后,可以继续深入互动",{_name_=skinConf.name}) ) -- 飘字
                end 

            end 
        end,
    })
end



-- 需手动调用 Delete()
function IdolLive3D_Demo:__delete()
    if self.events then
        CfUtils.EventsUndecorated(self.events)
    end
end


----------------------------------------------------------


function IdolLive3D_Demo:SelfUpdate()

    --- 自由轨道相机 是否在触发区间内:
    local isFreeTrackCameraInRange = self.idolLive3D_Main.idolLive3D_InteractiveManagerEnv:IsFreeTrackCameraInTargetIStateRange( self.tgtState )

    --- 是否在状态切换帧:
    local isChange = (self.isLastShow ~= self.isShow) or (self.isLastFreeTrackCameraInRange ~= isFreeTrackCameraInRange)
    self.isLastShow = self.isShow
    self.isLastFreeTrackCameraInRange = isFreeTrackCameraInRange
    ---
    if isChange then 
        if self.isShow and self.playTimes == 0 and isFreeTrackCameraInRange then 
            self.uiHandEnv:Show( true )
            self.uiHandEnv:PlayRemind()
            needShow = true
        else 
            self.uiHandEnv:Show( false )
        end 
    end

    ---
    if self.isShow and self.playTimes == 0 and isFreeTrackCameraInRange then 
        self.uiHandEnv:SetPos( self.tgtTF.position + self.demoJson.uiPosOffset )
    end 
end



function IdolLive3D_Demo:OnNewInteractiveState(iState_)
    local isTimeline = (iState_.stateType == StateType.Timeline)


    if self.state == State.Show then 

        if iState_.name == self.tgtState.name then 
            --- 目标 iState:
            self.playTimes = iState_.playTimes
        
            if iState_.playTimes > 0 then 
                self.isShow = false
                self.state = State.Finished
            else 
                self.isShow = true
            end

        else 
            --- 其它 iState:
            -- 只有在 idle 阶段才显示 ui手
            if iState_.stateType == StateType.Idle then 
                self.isShow = true
            else 
                self.isShow = false
            end 
        end

    elseif self.state == State.Finished then 
        ---
    else
        printError("state 值异常: " .. tostring(self.state))
    end 
end





return IdolLive3D_Demo
